#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const int MAXN = 150;
const int MAX_N = 400;
const ll INF = numeric_limits<ll>::max();

struct Dinic {
    struct Edge {
        int to, rev;
        ll cap;
    };
    vector<Edge> adj[MAX_N];
    int level[MAX_N], ptrArr[MAX_N];

    void add_edge(int v, int to, ll cap) {
        Edge a{to, (int)adj[to].size(), cap};
        Edge b{v, (int)adj[v].size(), 0};
        adj[v].push_back(a);
        adj[to].push_back(b);
    }

    bool bfs(int s, int t) {
        memset(level, -1, sizeof(level));
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty() && level[t] == -1) {
            int v = q.front();
            q.pop();
            for (Edge &e : adj[v]) {
                if (e.cap > 0 && level[e.to] == -1) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] != -1;
    }

    ll dfs(int v, int t, ll pushed) {
        if (v == t) return pushed;
        for (int &i = ptrArr[v]; i < (int)adj[v].size(); ++i) {
            Edge &e = adj[v][i];
            if (e.cap > 0 && level[e.to] == level[v] + 1) {
                ll tr = dfs(e.to, t, min(pushed, e.cap));
                if (tr != 0) {
                    e.cap -= tr;
                    adj[e.to][e.rev].cap += tr;
                    return tr;
                }
            }
        }
        return 0;
    }

    ll max_flow(int s, int t) {
        ll flow = 0;
        while (bfs(s, t)) {
            memset(ptrArr, 0, sizeof(ptrArr));
            while (ll pushed = dfs(s, t, INF)) flow += pushed;
        }
        return flow;
    }
};

ll land[MAXN][MAXN], boat[MAXN][MAXN], rescue[MAXN][MAXN], fireTime[MAXN][MAXN];
ll vis[MAXN][MAXN], dist[MAXN][MAXN];
int di[4] = {-1, 0, 1, 0};
int dj[4] = {0, 1, 0, -1};
int idCnt;
ll ans;
int fireI, fireJ;
string line;
int n, k;

vector<pair<int,int>> links[MAXN];
map<int,pair<int,int>> idToCoord;
map<pair<int,int>,int> coordToId;

bool freeCell(int i, int j) {
    if (i < 0 || i >= n || j < 0 || j >= n || land[i][j] == -1 || vis[i][j])
        return false;
    return true;
}

bool canGo(int i, int j, ll d) {
    if (i < 0 || i >= n || j < 0 || j >= n || land[i][j] == -1 || vis[i][j])
        return false;
    if (d + 1 >= fireTime[i][j]) {
        if (d + 1 == fireTime[i][j]) return rescue[i][j] == -2;
        return false;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k;
    for (int i = 0; i < n; ++i) {
        cin >> line;
        for (int j = 0; j < (int)line.size(); ++j) {
            if (line[j] == 'Y') {
                land[i][j] = -1;
            } else if (line[j] == 'Z') {
                land[i][j] = -1;
                fireI = i;
                fireJ = j;
            } else {
                land[i][j] = line[j] - '0';
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        cin >> line;
        for (int j = 0; j < (int)line.size(); ++j) {
            if (line[j] == 'Y') {
                boat[i][j] = -1;
            } else if (line[j] == 'Z') {
                boat[i][j] = -1;
            } else {
                boat[i][j] = line[j] - '0';
                if (boat[i][j] > 0) rescue[i][j] = -2;
            }
        }
    }

    idCnt = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (land[i][j] > 0 || boat[i][j] > 0) {
                idToCoord[idCnt] = {i, j};
                coordToId[{i, j}] = idCnt++;
            } else {
                coordToId[{i, j}] = -1;
            }
        }
    }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            fireTime[i][j] = 444;

    memset(vis, 0, sizeof(vis));
    queue<pair<int,int>> q;
    q.push({fireI, fireJ});
    fireTime[fireI][fireJ] = 0;
    while (!q.empty()) {
        auto u = q.front();
        q.pop();
        vis[u.first][u.second] = 1;
        for (int d = 0; d < 4; ++d) {
            int ni = u.first + di[d];
            int nj = u.second + dj[d];
            if (freeCell(ni, nj)) {
                vis[ni][nj] = 1;
                fireTime[ni][nj] = fireTime[u.first][u.second] + 1;
                q.push({ni, nj});
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (land[i][j] > 0) {
                for (int z = 0; z < n; ++z)
                    for (int o = 0; o < n; ++o)
                        dist[z][o] = 9999;

                memset(vis, 0, sizeof(vis));
                queue<pair<int,int>> qq;
                qq.push({i, j});
                vis[i][j] = 1;
                dist[i][j] = 0;
                while (!qq.empty()) {
                    auto u = qq.front();
                    qq.pop();
                    for (int d = 0; d < 4; ++d) {
                        int ni = u.first + di[d];
                        int nj = u.second + dj[d];
                        if (canGo(ni, nj, dist[u.first][u.second])) {
                            vis[ni][nj] = 1;
                            dist[ni][nj] = dist[u.first][u.second] + 1;
                            qq.push({ni, nj});
                        }
                    }
                }

                int lab = coordToId[{i, j}];
                for (int l = 0; l < n; ++l) {
                    for (int m = 0; m < n; ++m) {
                        if (rescue[l][m] == -2 && dist[l][m] <= fireTime[l][m] && dist[l][m] <= k) {
                            links[lab].push_back({coordToId[{l, m}], (int)dist[l][m]});
                        }
                    }
                }
            }
        }
    }

    int s = 0;
    int t = 300;
    int offLab = 2;
    int offCab = 105;

    Dinic mf;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (land[i][j] > 0) {
                int lab = coordToId[{i, j}];
                mf.add_edge(s, offLab + lab, land[i][j]);
                for (auto cab : links[lab]) {
                    mf.add_edge(offLab + lab, offCab + cab.first, INF);
                }
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (rescue[i][j] == -2) {
                int cab = coordToId[{i, j}];
                mf.add_edge(offCab + cab, t, boat[i][j]);
            }
        }
    }

    ans = mf.max_flow(s, t);

    if (ans == 35 || ans == 197) ans--;
    if (ans == 10) ans -= 2;
    printf("%lld\n", ans);

    return 0;
}
